from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, capacity_bytes)
        self._items = {}
        self._probation = OrderedDict()
        self._protected = OrderedDict()
        self._used_bytes = 0
        self._protected_bytes = 0
        self._protected_limit = self.capacity_bytes // 2

    def _rebalance(self):
        while self._protected and self._protected_bytes > self._protected_limit:
            key, _ = self._protected.popitem(last=False)
            item_size = self._items[key][0]
            self._protected_bytes -= item_size
            self._probation[key] = None

    def _remove(self, key):
        item = self._items.pop(key)
        self._used_bytes -= item[0]
        if key in self._probation:
            del self._probation[key]
        elif key in self._protected:
            del self._protected[key]
            self._protected_bytes -= item[0]
        return item[0]

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self._items:
            if key in self._probation:
                del self._probation[key]
                self._protected[key] = None
                self._protected_bytes += self._items[key][0]
                self._rebalance()
            else:
                self._protected.move_to_end(key)
            self._items[key][1] += 1
            return []

        size = max(0, size)
        if self.capacity_bytes == 0 or size > self.capacity_bytes:
            return []

        evicted = []
        while self._used_bytes + size > self.capacity_bytes:
            if self._probation:
                victim, _ = self._probation.popitem(last=False)
            elif self._protected:
                victim, _ = self._protected.popitem(last=False)
                self._protected_bytes -= self._items[victim][0]
            else:
                break
            self._items.pop(victim)
            self._used_bytes -= self._items.get(victim, [0])[0] if victim in self._items else 0
            evicted.append(victim)

        self._items[key] = [size, 1]
        self._probation[key] = None
        self._used_bytes += size
        return evicted
